function classify(d){const expectedBad=d.badResponses.filter(x=>(x.status===404&&/\/company\/finance\/operations\/(?:39|1000046)\/history/.test(x.url))||(x.status===403&&/\/company\/finance\/operations/.test(x.url)));const unexpectedBad=d.badResponses.filter(x=>!expectedBad.includes(x));const expectedConsole=d.consoleErrors.filter(x=>/\b(?:403|404)\b/.test(x)&&/Failed to load resource/i.test(x));const unexpectedConsole=d.consoleErrors.filter(x=>!expectedConsole.includes(x));return{unexpectedBad,unexpectedConsole,pageErrors:d.pageErrors,requestFailures:d.requestFailures,assetFailures:d.assetFailures};}
